//! IMRPhenomXHM with the original higher-mode amplitudes
//! (`PhenomXHMReleaseVersion = 122019`, as used by IMRPhenomXPNR) against
//! LALSimulation.
//!
//! The reference data are generated by `scripts/generate_reference_data.py`
//! (suites `imrphenomxhm_122019_modes` and `imrphenomxhm_122019`). The
//! binaries are chosen so that their modes go through every branch of the
//! release's amplitude reconstruction (vetoes of collocation points, the
//! order of the intermediate polynomial, two intermediate regions, ...).
mod common;

use num_complex::Complex;
use serde::Deserialize;
use waveformrs::grid::FrequencyGrid;
use waveformrs::imrphenomx::IMRPhenomXHM;

const RELEASE: u32 = 122019;

#[derive(Deserialize)]
struct ModeFile {
    lalsimulation_version: String,
    cases: Vec<ModeCase>,
}

#[derive(Deserialize)]
struct ModeCase {
    mass_1: f64,
    mass_2: f64,
    chi_1: f64,
    chi_2: f64,
    luminosity_distance: f64,
    phi_ref: f64,
    f_ref: f64,
    frequencies: Vec<f64>,
    modes: Vec<Mode>,
}

#[derive(Deserialize)]
struct Mode {
    ell: u32,
    emm: i32,
    real: Vec<f64>,
    imag: Vec<f64>,
}

/// Each higher mode against `SimIMRPhenomXHMFrequencySequenceOneMode`.
#[test]
fn imrphenomxhm_122019_modes_match_lalsimulation() {
    let path = common::data_path("imrphenomxhm_122019_modes");
    let reference: ModeFile =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut failures = Vec::new();
    let mut identical = 0;
    let mut total = 0;
    for case in &reference.cases {
        let xhm = IMRPhenomXHM::from_components(
            case.mass_1,
            case.mass_2,
            case.chi_1,
            case.chi_2,
            case.luminosity_distance,
        )
        .unwrap()
        .with_reference_frequency(case.f_ref)
        .with_release_version(RELEASE);
        for mode in &case.modes {
            let test = xhm.mode(mode.ell, mode.emm, &case.frequencies, case.phi_ref);
            let truth: Vec<common::C64> = mode
                .real
                .iter()
                .zip(&mode.imag)
                .map(|(&re, &im)| common::C64::new(re, im))
                .collect();
            let result = common::compare(&case.frequencies, &test, &truth);
            let exact = test == truth;
            total += 1;
            identical += exact as usize;
            println!(
                "({},{}): max rel err {:.3e}, mismatch {:.3e}{} | m1={} m2={} chi=({}, {})",
                mode.ell,
                mode.emm,
                result.max_relative_error,
                result.mismatch,
                if exact { " (identical)" } else { "" },
                case.mass_1,
                case.mass_2,
                case.chi_1,
                case.chi_2
            );
            // the cross-build tolerances of the IMRPhenomXHM modes
            let suite = if (mode.ell, mode.emm.abs()) == (3, 2) {
                "imrphenomxhm_modes_32"
            } else {
                "imrphenomxhm_modes"
            };
            let (rel, mm) = common::tolerances(suite, (1e-12, 1e-14));
            if !(result.max_relative_error <= rel && result.mismatch <= mm) {
                failures.push(format!(
                    "({},{}) {:?} m1={} m2={}",
                    mode.ell, mode.emm, result, case.mass_1, case.mass_2
                ));
            }
        }
    }
    println!("{identical} of {total} modes identical to lalsimulation");
    assert!(
        failures.is_empty(),
        "modes differ from lalsimulation {}:\n{}",
        reference.lalsimulation_version,
        failures.join("\n")
    );
}

/// The polarizations against `SimInspiralChooseFDWaveformSequence` (no
/// multibanding), where the (3,2) recycles the (2,2) in its ringdown.
#[test]
fn imrphenomxhm_122019_matches_lalsimulation() {
    common::check_all("imrphenomxhm_122019", 1e-12, 1e-14, |case| {
        assert_eq!(case.lal_flags["PhenomXHMReleaseVersion"], RELEASE as f64);
        IMRPhenomXHM::from_components(
            case.mass_1,
            case.mass_2,
            case.spin_1[2],
            case.spin_2[2],
            case.luminosity_distance,
        )
        .unwrap()
        .with_reference_frequency(case.f_ref)
        .with_release_version(RELEASE)
        .polarizations(&case.frequencies, case.phi_ref, case.inclination)
    });
}

/// The grid path agrees with the frequency-sequence path to rounding.
#[test]
fn imrphenomxhm_122019_on_grids() {
    let grids = [
        FrequencyGrid::uniform(10.0, 1024.0, 0.125),
        FrequencyGrid::new(&(0..600).map(|i| 8.0 * 1.01_f64.powi(i)).collect::<Vec<_>>()),
    ];
    for (m1, m2, chi1, chi2) in [
        (36.0, 29.0, 0.3, -0.4),
        (79.0458, 0.2689, -0.89, 0.959),
        (109.45, 109.45, -0.947, -0.947),
        (100.9494, 12.6503, 0.988, -0.02),
    ] {
        let model = IMRPhenomXHM::from_components(m1, m2, chi1, chi2, 400.0)
            .unwrap()
            .with_reference_frequency(20.0)
            .with_release_version(RELEASE);
        for grid in &grids {
            let (plus, cross) = model.polarizations(grid.frequencies(), 0.3, 0.7);
            let zero = Complex::new(0.0, 0.0);
            let (mut gp, mut gc) = (vec![zero; grid.len()], vec![zero; grid.len()]);
            model.polarizations_on_grid(grid, 0.3, 0.7, &mut gp, &mut gc);
            for (test, truth) in [(&gp, &plus), (&gc, &cross)] {
                let result = common::compare(grid.frequencies(), test, truth);
                assert!(
                    result.max_relative_error < 1e-10,
                    "m1={m1} m2={m2}: {result:?}"
                );
            }
        }
    }
}

/// The default release is 122022 and differs from 122019.
#[test]
fn release_versions_differ() {
    let frequencies: Vec<f64> = (0..64).map(|i| 20.0 + 6.0 * i as f64).collect();
    let new = IMRPhenomXHM::new(60.0, 0.25, 0.4, -0.2, 400.0);
    let old = new.clone().with_release_version(RELEASE);
    for (l, m) in [(2, -1), (3, -3), (3, -2), (4, -4)] {
        let a = new.mode(l, m, &frequencies, 0.0);
        let b = new
            .clone()
            .with_release_version(122022)
            .mode(l, m, &frequencies, 0.0);
        assert_eq!(a, b);
        let c = old.mode(l, m, &frequencies, 0.0);
        assert_ne!(a, c, "({l},{m})");
    }
    // The (2,2) mode is the same in both releases.
    assert_eq!(
        new.mode(2, -2, &frequencies, 0.0),
        old.mode(2, -2, &frequencies, 0.0)
    );
}

#[test]
#[should_panic(expected = "PhenomXHMReleaseVersion")]
fn invalid_release_version_panics() {
    let _ = IMRPhenomXHM::new(60.0, 0.25, 0.4, -0.2, 400.0).with_release_version(122020);
}
